"""Copy yesterday's rows from production into the reporting warehouse."""

from __future__ import annotations

from datetime import date, timedelta

TABLES = ("accounts", "invoices", "payments")


def window(today: date) -> tuple[date, date]:
    """The day to load: all of yesterday."""
    start = today - timedelta(days=1)
    return start, today


def batches(rows: int, size: int = 5000) -> int:
    """How many batches a load of `rows` takes."""
    if size <= 0:
        raise ValueError("batch size must be positive")
    return -(-rows // size)

